('dqp_s1_01','saussure','QUIZ','vocabulary','{"question":"다음 중 사과의 뜻으로 올바른 것은?","choices":["빨간색 과일","노란색 채소","파란색 꽃","초록색 나무"],"answerIndex":0,"explanation":"사과는 빨간색 또는 초록색 과일입니다."}','ACTIVE',NOW(),NOW()),
