('dqp_s1_03','saussure','QUIZ','grammar','{"question":"나는 학교에 갑니다 에서 주어는?","choices":["나는","학교에","갑니다","학교"],"answerIndex":0,"explanation":"나는이 문장의 주어입니다."}','ACTIVE',NOW(),NOW()),
