('dqp_s1_05','saussure','QUIZ','vocabulary','{"question":"크다의 반대말은?","choices":["작다","높다","길다","넓다"],"answerIndex":0,"explanation":"크다의 반대말은 작다입니다."}','ACTIVE',NOW(),NOW()),
