('dqp_s1_07','saussure','QUIZ','grammar','{"question":"예쁜 꽃이 피었습니다 에서 꾸며주는 말은?","choices":["예쁜","꽃이","피었습니다","꽃"],"answerIndex":0,"explanation":"예쁜은 꽃을 꾸며주는 말(관형어)입니다."}','ACTIVE',NOW(),NOW()),
('dqp_s1_08','saussure','QUIZ','vocabulary','{"question":"봄에 볼 수 있는 것은?","choices":["벚꽃","눈사람","낙엽","고드름"],"answerIndex":0,"explanation":"벚꽃은 봄에 피는 꽃입니다."}','ACTIVE',NOW(),NOW()),
('dqp_s1_09','saussure','READING','comprehension','{"passage":"토끼와 거북이가 달리기를 했습니다. 토끼는 빨리 달렸지만 중간에 낮잠을 잤습니다. 거북이는 느리지만 쉬지 않고 달려서 먼저 도착했습니다.","question":"달리기에서 이긴 동물은?","choices":["토끼","거북이","둘 다","아무도"],"answerIndex":1,"explanation":"거북이가 쉬지 않고 달려서 먼저 도착했습니다."}','ACTIVE',NOW(),NOW()),
('dqp_s1_10','saussure','READING','comprehension','{"passage":"민수는 아침에 일어나서 세수를 하고 밥을 먹었습니다. 그리고 가방을 메고 학교에 갔습니다.","question":"민수가 밥을 먹기 전에 한 것은?","choices":["세수","학교 가기","가방 메기","공부"],"answerIndex":0,"explanation":"민수는 세수를 하고 나서 밥을 먹었습니다."}','ACTIVE',NOW(),NOW()),
('dqp_s1_11','saussure','READING','comprehension','{"passage":"하늘에서 비가 내립니다. 사람들은 우산을 쓰고 걸어갑니다. 아이들은 장화를 신고 물웅덩이에서 놀고 있습니다.","question":"사람들이 우산을 쓴 이유는?","choices":["비가 와서","눈이 와서","바람이 불어서","더워서"],"answerIndex":0,"explanation":"비가 내리기 때문에 우산을 쓴 것입니다."}','ACTIVE',NOW(),NOW()),
('dqp_s1_12','saussure','READING','comprehension','{"passage":"엄마가 시장에서 사과 세 개와 배 두 개를 샀습니다. 집에 와서 사과 한 개를 먹었습니다.","question":"엄마가 시장에서 산 과일은 모두 몇 개?","choices":["세 개","네 개","다섯 개","여섯 개"],"answerIndex":2,"explanation":"사과 3개 + 배 2개 = 5개입니다."}','ACTIVE',NOW(),NOW()),
('dqp_s1_13','saussure','READING','comprehension','{"passage":"강아지가 공원에서 놀고 있습니다. 강아지는 공을 물고 주인에게 가져다줍니다. 주인은 다시 공을 던져줍니다.","question":"강아지가 하는 놀이는?","choices":["공 가져오기","달리기","수영","숨바꼭질"],"answerIndex":0,"explanation":"강아지는 공을 물고 주인에게 가져다주는 놀이를 합니다."}','ACTIVE',NOW(),NOW()),
('dqp_f1_01','frege','QUIZ','vocabulary','{"question":"다음 중 관용 표현에 해당하는 것은?","choices":["발이 넓다","키가 크다","머리가 길다","손이 작다"],"answerIndex":0,"explanation":"발이 넓다는 아는 사람이 많다는 뜻의 관용 표현입니다."}','ACTIVE',NOW(),NOW()),
('dqp_f1_02','frege','QUIZ','grammar','{"question":"다음 중 높임말이 올바르게 쓰인 것은?","choices":["할머니께서 오셨습니다","할머니가 왔다","할머니 와","할머니가 옵니다"],"answerIndex":0,"explanation":"께서와 -셨습니다를 사용한 높임 표현이 올바릅니다."}','ACTIVE',NOW(),NOW()),
('dqp_f1_03','frege','QUIZ','vocabulary','{"question":"희로애락에서 애의 뜻은?","choices":["기쁨","노여움","슬픔","즐거움"],"answerIndex":2,"explanation":"희(기쁨), 로(노여움), 애(슬픔), 락(즐거움)입니다."}','ACTIVE',NOW(),NOW()),
('dqp_f1_04','frege','QUIZ','grammar','{"question":"다음 중 띄어쓰기가 올바른 것은?","choices":["나는 학생입니다","나는학생입니다","나 는 학생입니다","나는 학생 입니다"],"answerIndex":0,"explanation":"조사는 앞 단어에 붙여 쓰고, 단어 사이는 띄어 씁니다."}','ACTIVE',NOW(),NOW()),
('dqp_f1_05','frege','QUIZ','vocabulary','{"question":"고진감래의 뜻은?","choices":["쓴 것이 다하면 단 것이 온다","빨리 가면 늦게 온다","높은 곳에서 떨어진다","옛것이 새것보다 낫다"],"answerIndex":0,"explanation":"고진감래는 고생 끝에 즐거움이 온다는 뜻입니다."}','ACTIVE',NOW(),NOW()),
('dqp_f1_06','frege','QUIZ','grammar','{"question":"먹다의 높임말은?","choices":["드시다","먹으시다","잡수다","드시다와 잡수시다 모두"],"answerIndex":3,"explanation":"먹다의 높임말은 드시다와 잡수시다 모두 사용할 수 있습니다."}','ACTIVE',NOW(),NOW()),
('dqp_f1_07','frege','QUIZ','vocabulary','{"question":"다음 중 의성어는?","choices":["반짝반짝","멍멍","살금살금","울퉁불퉁"],"answerIndex":1,"explanation":"멍멍은 개 짖는 소리를 나타내는 의성어입니다."}','ACTIVE',NOW(),NOW()),
('dqp_f1_08','frege','QUIZ','grammar','{"question":"다음 문장에서 서술어는? 새가 하늘을 날았다","choices":["새가","하늘을","날았다","하늘"],"answerIndex":2,"explanation":"날았다가 이 문장의 서술어입니다."}','ACTIVE',NOW(),NOW()),
('dqp_f1_09','frege','READING','comprehension','{"passage":"개미는 여름 동안 열심히 먹이를 모았습니다. 반면 베짱이는 노래만 부르며 놀았습니다. 겨울이 되자 개미는 따뜻한 집에서 먹이를 먹었지만, 베짱이는 추위와 배고픔에 떨어야 했습니다.","question":"이 이야기의 교훈은?","choices":["미리 준비하는 것이 중요하다","노래를 잘 부르면 된다","겨울은 추운 계절이다","개미가 베짱이보다 강하다"],"answerIndex":0,"explanation":"이 이야기는 미리 준비하는 것의 중요성을 알려줍니다."}','ACTIVE',NOW(),NOW()),
('dqp_f1_10','frege','READING','comprehension','{"passage":"세종대왕은 백성들이 글을 읽고 쓰지 못하는 것을 안타깝게 여겼습니다. 그래서 누구나 쉽게 배울 수 있는 한글을 만들었습니다. 한글은 1443년에 완성되었습니다.","question":"세종대왕이 한글을 만든 이유는?","choices":["백성이 글을 몰라서","중국어가 어려워서","새 문자가 필요해서","학자들의 요청으로"],"answerIndex":0,"explanation":"백성들이 글을 읽고 쓰지 못하는 것을 안타깝게 여겨 한글을 만들었습니다."}','ACTIVE',NOW(),NOW()),
('dqp_f1_11','frege','READING','comprehension','{"passage":"도서관에는 다양한 종류의 책이 있습니다. 소설, 과학책, 역사책, 만화책 등이 있습니다. 도서관에서는 조용히 해야 하며, 책을 빌릴 때는 도서관 카드가 필요합니다.","question":"도서관에서 책을 빌리려면 필요한 것은?","choices":["돈","도서관 카드","선생님 허락","학생증"],"answerIndex":1,"explanation":"책을 빌릴 때는 도서관 카드가 필요합니다."}','ACTIVE',NOW(),NOW()),
('dqp_f1_12','frege','READING','comprehension','{"passage":"지구는 태양 주위를 돌고 있습니다. 지구가 태양을 한 바퀴 도는 데 약 365일이 걸립니다. 이것을 1년이라고 합니다. 지구가 스스로 한 바퀴 도는 데는 약 24시간이 걸리며, 이것을 하루라고 합니다.","question":"지구가 태양을 한 바퀴 도는 시간은?","choices":["하루","한 달","1년","24시간"],"answerIndex":2,"explanation":"지구가 태양을 한 바퀴 도는 데 약 365일, 즉 1년이 걸립니다."}','ACTIVE',NOW(),NOW()),
('dqp_f1_13','frege','READING','comprehension','{"passage":"김치는 한국의 대표적인 음식입니다. 배추, 무, 고춧가루, 젓갈 등을 넣어 만듭니다. 김치에는 비타민과 유산균이 풍부하여 건강에 좋습니다.","question":"김치에 풍부한 것은?","choices":["설탕과 소금","비타민과 유산균","단백질과 지방","칼슘과 철분"],"answerIndex":1,"explanation":"김치에는 비타민과 유산균이 풍부합니다."}','ACTIVE',NOW(),NOW()),
('dqp_r1_01','russell','QUIZ','vocabulary','{"question":"다음 중 역설의 의미로 올바른 것은?","choices":["모순되는 듯하지만 진리를 담은 표현","거짓된 주장","반복적인 설명","논리적인 증명"],"answerIndex":0,"explanation":"역설은 겉으로는 모순되는 듯하지만 깊은 진리를 담고 있는 표현입니다."}','ACTIVE',NOW(),NOW()),
('dqp_r1_02','russell','QUIZ','grammar','{"question":"다음 중 피동 표현이 올바른 것은?","choices":["문이 열렸다","문을 열렸다","문이 열렸다가","문을 열려졌다"],"answerIndex":0,"explanation":"문이 열렸다가 올바른 피동 표현입니다."}','ACTIVE',NOW(),NOW()),
('dqp_r1_03','russell','QUIZ','vocabulary','{"question":"풍전등화의 뜻은?","choices":["바람 앞의 등불처럼 위태로운 상황","바람이 부는 아름다운 밤","등불을 켠 풍경","전쟁 중의 등불"],"answerIndex":0,"explanation":"풍전등화는 바람 앞의 등불처럼 매우 위태로운 처지를 뜻합니다."}','ACTIVE',NOW(),NOW()),
('dqp_r1_04','russell','QUIZ','grammar','{"question":"다음 중 사동 표현에 해당하는 것은?","choices":["엄마가 아이에게 옷을 입혔다","아이가 옷을 입었다","옷이 예쁘다","아이가 웃었다"],"answerIndex":0,"explanation":"입히다는 다른 사람에게 행동을 시키는 사동 표현입니다."}','ACTIVE',NOW(),NOW()),
('dqp_r1_05','russell','QUIZ','vocabulary','{"question":"아이러니의 뜻은?","choices":["기대와 반대되는 결과","예상대로의 결과","반복되는 현상","빠른 변화"],"answerIndex":0,"explanation":"아이러니는 기대나 예상과 반대되는 결과가 나타나는 것을 뜻합니다."}','ACTIVE',NOW(),NOW()),
('dqp_r1_06','russell','QUIZ','grammar','{"question":"철수가 도서관에서 책을 읽었다 - 문장 성분 분석이 올바른 것은?","choices":["주어-부사어-목적어-서술어","주어-목적어-부사어-서술어","주어-서술어-목적어-부사어","부사어-주어-목적어-서술어"],"answerIndex":0,"explanation":"철수가(주어) 도서관에서(부사어) 책을(목적어) 읽었다(서술어)입니다."}','ACTIVE',NOW(),NOW()),
('dqp_r1_07','russell','QUIZ','vocabulary','{"question":"은유란 무엇인가?","choices":["A는 B이다 형식의 비유","A는 B 같다 형식의 비유","소리를 흉내 내는 말","과장하여 표현하는 것"],"answerIndex":0,"explanation":"은유는 ~처럼, ~같이 없이 직접 빗대어 표현하는 비유법입니다."}','ACTIVE',NOW(),NOW()),
('dqp_r1_08','russell','QUIZ','grammar','{"question":"다음 중 겹문장은?","choices":["비가 오고 바람이 분다","비가 온다","바람이 분다","하늘이 맑다"],"answerIndex":0,"explanation":"비가 오고 바람이 분다는 두 개의 절이 결합된 겹문장입니다."}','ACTIVE',NOW(),NOW()),
('dqp_r1_09','russell','READING','comprehension','{"passage":"소설에서 서술자는 이야기를 전달하는 사람입니다. 1인칭 서술자는 등장인물이 직접 이야기하며, 3인칭 서술자는 밖에서 관찰합니다. 서술자의 시점에 따라 이야기의 분위기와 독자가 얻는 정보가 달라집니다.","question":"1인칭 서술의 특징은?","choices":["등장인물이 직접 이야기한다","밖에서 관찰한다","모든 것을 안다","객관적이다"],"answerIndex":0,"explanation":"1인칭 서술자는 등장인물이 직접 이야기를 전달합니다."}','ACTIVE',NOW(),NOW()),
('dqp_r1_10','russell','READING','comprehension','{"passage":"논설문은 자신의 주장을 논리적으로 펼치는 글입니다. 논설문은 서론, 본론, 결론으로 구성됩니다. 서론에서 문제를 제기하고, 본론에서 근거를 들어 주장을 펼치며, 결론에서 주장을 정리합니다.","question":"논설문의 본론에서 하는 것은?","choices":["문제 제기","근거를 들어 주장","주장 정리","인사말"],"answerIndex":1,"explanation":"본론에서는 근거를 들어 주장을 펼칩니다."}','ACTIVE',NOW(),NOW()),
('dqp_r1_11','russell','READING','comprehension','{"passage":"한국어의 높임법에는 주체 높임, 객체 높임, 상대 높임이 있습니다. 주체 높임은 문장의 주어를 높이는 것이고, 객체 높임은 목적어나 부사어가 지시하는 대상을 높이는 것이며, 상대 높임은 듣는 이를 높이는 것입니다.","question":"듣는 이를 높이는 높임법은?","choices":["주체 높임","객체 높임","상대 높임","간접 높임"],"answerIndex":2,"explanation":"상대 높임은 듣는 이를 높이는 높임법입니다."}','ACTIVE',NOW(),NOW()),
('dqp_r1_12','russell','READING','comprehension','{"passage":"비유법에는 직유법, 은유법, 의인법 등이 있습니다. 직유법은 ~처럼, ~같이를 사용하여 비유하고, 은유법은 원관념을 보조관념으로 직접 표현합니다. 의인법은 사람이 아닌 것을 사람처럼 표현합니다.","question":"의인법이란?","choices":["~처럼을 사용한 비유","직접 빗대어 표현","사람 아닌 것을 사람처럼","과장하여 표현"],"answerIndex":2,"explanation":"의인법은 사람이 아닌 것을 사람처럼 표현하는 비유법입니다."}','ACTIVE',NOW(),NOW()),
('dqp_r1_13','russell','READING','comprehension','{"passage":"수필은 형식에 얽매이지 않고 자유롭게 쓴 글입니다. 수필의 특징은 개성적이고 비전문적이며, 일상의 경험이나 생각을 솔직하게 표현합니다. 붓 가는 대로 쓴다는 뜻에서 수필이라 합니다.","question":"수필의 특징이 아닌 것은?","choices":["형식이 자유롭다","개성적이다","전문적이고 학술적이다","솔직하게 표현한다"],"answerIndex":2,"explanation":"수필은 비전문적이고 자유로운 글이며, 전문적이고 학술적인 글이 아닙니다."}','ACTIVE',NOW(),NOW()),
('dqp_w1_01','wittgenstein','QUIZ','vocabulary','{"question":"다음 중 형이상학적의 의미로 올바른 것은?","choices":["감각을 초월한 근본 원리에 관한","물리적이고 구체적인","역사적 사실에 근거한","수학적으로 증명 가능한"],"answerIndex":0,"explanation":"형이상학적은 경험을 초월한 근본적인 원리나 존재에 관한 것을 뜻합니다."}','ACTIVE',NOW(),NOW()),
('dqp_w1_02','wittgenstein','QUIZ','grammar','{"question":"다음 중 중의적 표현에 해당하는 것은?","choices":["예쁜 친구의 동생","빠른 자동차","높은 산","넓은 바다"],"answerIndex":0,"explanation":"예쁜 친구의 동생은 예쁜이 친구를 수식하는지 동생을 수식하는지 모호합니다."}','ACTIVE',NOW(),NOW()),
('dqp_w1_03','wittgenstein','QUIZ','vocabulary','{"question":"해체주의의 핵심 개념은?","choices":["고정된 의미의 해체와 다양한 해석 가능성","전통의 보존과 계승","논리적 체계의 구축","과학적 방법론의 적용"],"answerIndex":0,"explanation":"해체주의는 텍스트의 고정된 의미를 해체하고 다양한 해석 가능성을 탐구합니다."}','ACTIVE',NOW(),NOW()),
('dqp_w1_04','wittgenstein','QUIZ','grammar','{"question":"다음 중 내포문에 해당하는 것은?","choices":["나는 그가 올 것을 안다","비가 온다","꽃이 피었다","바람이 분다"],"answerIndex":0,"explanation":"그가 올 것을이라는 절이 안긴 내포문입니다."}','ACTIVE',NOW(),NOW()),
('dqp_w1_05','wittgenstein','QUIZ','vocabulary','{"question":"상호텍스트성이란?","choices":["텍스트 간의 영향과 관계","작가의 전기적 사실","독자의 감정 반응","텍스트의 물리적 형태"],"answerIndex":0,"explanation":"상호텍스트성은 하나의 텍스트가 다른 텍스트와 맺는 관계와 영향을 말합니다."}','ACTIVE',NOW(),NOW()),
('dqp_w1_06','wittgenstein','QUIZ','grammar','{"question":"다음 중 담화 표지에 해당하는 것은?","choices":["그런데","사과","학교","하늘"],"answerIndex":0,"explanation":"그런데는 담화의 흐름을 조절하는 담화 표지입니다."}','ACTIVE',NOW(),NOW()),
('dqp_w1_07','wittgenstein','QUIZ','vocabulary','{"question":"서사 구조에서 위기의 역할은?","choices":["갈등이 최고조에 달하는 부분","이야기의 시작","결말 이후의 여운","배경 설명"],"answerIndex":0,"explanation":"위기는 갈등이 최고조에 달하여 긴장감이 극대화되는 부분입니다."}','ACTIVE',NOW(),NOW()),
('dqp_w1_08','wittgenstein','QUIZ','grammar','{"question":"다음 중 화용론에서 다루는 것은?","choices":["맥락에 따른 의미 해석","단어의 어원","문장의 구조 분석","음운의 변동"],"answerIndex":0,"explanation":"화용론은 언어가 실제 사용되는 맥락에서의 의미를 연구합니다."}','ACTIVE',NOW(),NOW()),
('dqp_w1_09','wittgenstein','READING','comprehension','{"passage":"소쉬르는 언어를 랑그(langue)와 파롤(parole)로 구분했습니다. 랑그는 사회적으로 공유되는 언어 체계이고, 파롤은 개인이 실제로 사용하는 발화입니다. 이 구분은 구조주의 언어학의 토대가 되었습니다.","question":"소쉬르의 랑그란?","choices":["사회적 언어 체계","개인의 발화","언어의 역사","방언의 종류"],"answerIndex":0,"explanation":"랑그는 사회 구성원들이 공유하는 추상적인 언어 체계입니다."}','ACTIVE',NOW(),NOW()),
('dqp_w1_10','wittgenstein','READING','comprehension','{"passage":"모더니즘 문학은 전통적 서사 방식을 거부하고 새로운 형식을 실험했습니다. 의식의 흐름 기법, 비선형적 시간 구성, 다중 시점 등을 활용하여 인간 내면의 복잡성을 표현하고자 했습니다.","question":"모더니즘 문학의 특징이 아닌 것은?","choices":["전통 서사 거부","의식의 흐름","선형적 시간 구성","다중 시점"],"answerIndex":2,"explanation":"모더니즘 문학은 비선형적 시간 구성을 특징으로 하며, 선형적 구성은 전통적 방식입니다."}','ACTIVE',NOW(),NOW()),
('dqp_w1_11','wittgenstein','READING','comprehension','{"passage":"비트겐슈타인은 초기 저작에서 언어와 세계의 논리적 대응을 주장했으나, 후기에는 언어의 의미가 사용에 의해 결정된다는 언어 게임 이론을 제시했습니다. 이는 언어의 의미가 고정되어 있지 않고 맥락에 따라 변한다는 것을 의미합니다.","question":"비트겐슈타인 후기 철학의 핵심은?","choices":["언어와 세계의 대응","언어의 의미는 사용에 의해 결정","논리적 원자론","형식 논리학"],"answerIndex":1,"explanation":"후기 비트겐슈타인은 언어의 의미가 사용과 맥락에 의해 결정된다고 보았습니다."}','ACTIVE',NOW(),NOW()),
('dqp_w1_12','wittgenstein','READING','comprehension','{"passage":"문학 비평에서 독자 반응 비평은 텍스트의 의미가 독자와의 상호작용을 통해 생성된다고 봅니다. 작품의 의미는 텍스트 자체에 내재하는 것이 아니라, 독자가 텍스트를 읽는 과정에서 능동적으로 구성하는 것입니다.","question":"독자 반응 비평에서 의미는 어디에서 생성되는가?","choices":["텍스트 자체","작가의 의도","독자와 텍스트의 상호작용","사회적 맥락"],"answerIndex":2,"explanation":"독자 반응 비평은 독자와 텍스트의 상호작용에서 의미가 생성된다고 봅니다."}','ACTIVE',NOW(),NOW()),
('dqp_w1_13','wittgenstein','READING','comprehension','{"passage":"프레게는 의미론에서 뜻(Sinn)과 지시체(Bedeutung)를 구분했습니다. 샛별과 개밥바라기는 같은 지시체(금성)를 가리키지만, 뜻은 다릅니다. 이 구분은 언어 철학의 핵심 개념이 되었습니다.","question":"프레게의 이론에서 샛별과 개밥바라기의 관계는?","choices":["뜻은 같고 지시체가 다르다","뜻은 다르고 지시체가 같다","뜻도 지시체도 같다","뜻도 지시체도 다르다"],"answerIndex":1,"explanation":"샛별과 개밥바라기는 같은 금성을 가리키지만(지시체 동일), 표현하는 방식(뜻)은 다릅니다."}','ACTIVE',NOW(),NOW());
